#!/usr/bin/env bash
# NEXYRA Automation v3.3.0-R2 - revendedor - instalacao direta sem GitHub token.
# Contem pacote do REVENDEDOR R2 EMBUTIDO; NAO contem um backup do MASTER.
# CUIDADO: este script sera PUBLICO se enviado a um repositorio publico.
set -Eeuo pipefail
umask 077
say(){ printf '\n[NEXYRA] %s\n' "$*"; }
fail(){ printf '\n[NEXYRA ERRO] %s\n' "$*" >&2; exit 1; }
if [[ "${1:-}" != "--verificar" ]]; then
  [[ "$(id -u)" -eq 0 ]] || fail 'Execute como root em uma VPS nova.'
  [[ ! -e /opt/nexyra-cliente ]] || fail 'NEXYRA ja instalado: nao sera sobrescrito.'
fi
command -v python3 >/dev/null || fail 'Python3 indisponivel (Ubuntu/Debian recomendado).'
[[ -r "$0" ]] || fail 'Nao consigo ler o instalador local.'
workdir="$(mktemp -d /tmp/nexyra-r2-direto.XXXXXXXX)" || fail 'Falha criando diretorio temporario.'
trap 'rm -rf -- "$workdir"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
say 'Extraindo pacote NEXYRA R2 embutido e verificando integridade...'
python3 - "$0" "$workdir" <<'PYEXTRACT'
from pathlib import Path
from zipfile import ZipFile
import base64, hashlib, io, stat, sys
origin=Path(sys.argv[1]); dest=Path(sys.argv[2]).resolve()
raw=origin.read_bytes()
marker=b": <<'NEXYRA_BUNDLE_END_R2'\n"
if marker not in raw: raise SystemExit('Erro: pacote embutido nao localizado')
encoded=raw.split(marker,1)[1].split(b'\nNEXYRA_BUNDLE_END_R2',1)[0].strip()
try: content=base64.b64decode(b"".join(encoded.split()),validate=True)
except Exception as ex: raise SystemExit('Erro decodificando o pacote: '+str(ex))
expected='1f177a5a1d13548c71e7b42c09f44d30b92e5d28e0c12b5985b2b2424c619296'
actual=hashlib.sha256(content).hexdigest()
if actual != expected: raise SystemExit('Assinatura SHA-256 do ZIP incorreta: instalacao bloqueada')
with ZipFile(io.BytesIO(content)) as z:
    infos=z.infolist()
    if len(infos)>150 or sum(x.file_size for x in infos)>100_000_000:
        raise SystemExit('ZIP fora dos limites de tamanho')
    for x in infos:
        candidate=(dest/x.filename).resolve()
        if candidate!=dest and dest not in candidate.parents: raise SystemExit('Caminho inseguro no ZIP')
        if stat.S_ISLNK(x.external_attr >> 16): raise SystemExit('ZIP contem links simbolicos')
    z.extractall(dest)
install=dest/'NEXYRA-REVENDEDOR-LAB'/'INSTALAR.sh'
evo=dest/'NEXYRA-REVENDEDOR-LAB'/'app'/'backend'/'evolution.js'
if not install.is_file() or not evo.is_file(): raise SystemExit('Arquivos obrigatorios ausentes')
if b'sendImage' not in evo.read_bytes(): raise SystemExit('Pacote sem hotfix de imagem PIX')
print('[OK] ZIP R2 integro, arquivos validados, correcao PIX presente')
PYEXTRACT
if [[ "${1:-}" == "--verificar" ]]; then
  say 'TESTE DE PACOTE PASSOU (sem instalar nada).'
  exit 0
fi
say 'NEXYRA R2 pronto. Serao solicitados dominio base, ID da VPS e token da LICENCA MASTER.'
say 'DNS api./painel./portal. deve apontar para esta VPS; portas 80/443 devem estar livres.'
bash "$workdir/NEXYRA-REVENDEDOR-LAB/INSTALAR.sh" || fail 'Instalacao falhou. Verifique o erro; nao tente reinstalar por cima.'
say 'Instalacao concluida. Configure e valide o painel em modo SIMULACAO antes de pagamentos reais.'
exit 0
# Pacote da aplicacao do revendedor, apenas distribuido com autorizacao do proprietario.
: <<'NEXYRA_BUNDLE_END_R2'
